const state = await appStore.getState();
const data = state && typeof state === "object" ? state : {};

const HABITS_KEY = "habits";
const CHECKINS_KEY = "checkins";

const existingHabits = Array.isArray(data[HABITS_KEY]) ? data[HABITS_KEY] : null;
const habits = existingHabits ? existingHabits.slice() : [];
const checkins = data[CHECKINS_KEY] && typeof data[CHECKINS_KEY] === "object" && !Array.isArray(data[CHECKINS_KEY])
  ? Object.assign({}, data[CHECKINS_KEY])
  : {};

const el = {
  todayLabel: document.querySelector('[data-role="today-label"]'),
  doneCount: document.querySelector('[data-role="done-count"]'),
  totalCount: document.querySelector('[data-role="total-count"]'),
  progressFill: document.querySelector('[data-role="progress-fill"]'),
  addForm: document.querySelector('[data-role="add-form"]'),
  nameInput: document.querySelector('[data-role="name-input"]'),
  formMessage: document.querySelector('[data-role="form-message"]'),
  habitList: document.querySelector('[data-role="habit-list"]'),
  listCount: document.querySelector('[data-role="list-count"]'),
  emptyState: document.querySelector('[data-role="empty-state"]'),
  dialogBackdrop: document.querySelector('[data-role="dialog-backdrop"]'),
  dialogText: document.querySelector('[data-role="dialog-text"]'),
  dialogCancel: document.querySelector('[data-role="dialog-cancel"]'),
  dialogConfirm: document.querySelector('[data-role="dialog-confirm"]')
};

function pad2(n) {
  return n < 10 ? "0" + n : String(n);
}

function todayKey() {
  const d = new Date();
  return d.getFullYear() + "-" + pad2(d.getMonth() + 1) + "-" + pad2(d.getDate());
}

function todayText() {
  const d = new Date();
  const week = ["日", "一", "二", "三", "四", "五", "六"][d.getDay()];
  return d.getFullYear() + " 年 " + (d.getMonth() + 1) + " 月 " + d.getDate() + " 日 · 星期" + week;
}

function makeId() {
  return "h_" + Date.now().toString(36) + "_" + Math.random().toString(36).slice(2, 8);
}

function normalizeHabit(raw) {
  if (!raw || typeof raw !== "object") return null;
  const name = typeof raw.name === "string" ? raw.name : "";
  const id = typeof raw.id === "string" && raw.id ? raw.id : makeId();
  const createdAt = typeof raw.createdAt === "string" ? raw.createdAt : new Date().toISOString();
  return Object.assign({}, raw, { id: id, name: name, createdAt: createdAt });
}

function isDoneToday(habitId) {
  const day = checkins[todayKey()];
  if (!day || typeof day !== "object") return false;
  return day[habitId] === true;
}

function doneCountToday() {
  return habits.filter(function (h) { return isDoneToday(h.id); }).length;
}

function setMessage(text, kind) {
  el.formMessage.textContent = text || "";
  el.formMessage.classList.remove("is-error", "is-ok");
  if (kind === "error") el.formMessage.classList.add("is-error");
  if (kind === "ok") el.formMessage.classList.add("is-ok");
}

function renderStats() {
  const total = habits.length;
  const done = doneCountToday();
  el.doneCount.textContent = String(done);
  el.totalCount.textContent = String(total);
  el.progressFill.style.width = total > 0 ? Math.round((done / total) * 100) + "%" : "0%";
  el.listCount.textContent = total > 0 ? "共 " + total + " 个" : "";
}

function renderList() {
  el.habitList.textContent = "";
  el.emptyState.hidden = habits.length > 0;

  habits.forEach(function (habit) {
    const li = document.createElement("li");
    li.className = "habit-item" + (isDoneToday(habit.id) ? " is-done" : "");
    li.dataset.habitId = habit.id;

    const checkbox = document.createElement("input");
    checkbox.type = "checkbox";
    checkbox.className = "habit-check";
    checkbox.checked = isDoneToday(habit.id);
    checkbox.dataset.role = "toggle";
    checkbox.setAttribute("aria-label", "标记今天完成：" + habit.name);

    const label = document.createElement("label");
    label.className = "habit-label";

    const nameSpan = document.createElement("span");
    nameSpan.className = "habit-name";
    nameSpan.textContent = habit.name;

    const meta = document.createElement("span");
    meta.className = "habit-meta";
    meta.textContent = isDoneToday(habit.id) ? "今天已完成" : "今天未完成";

    label.appendChild(checkbox);
    label.appendChild(nameSpan);
    label.appendChild(meta);

    const del = document.createElement("button");
    del.type = "button";
    del.className = "habit-delete";
    del.dataset.role = "delete";
    del.textContent = "删除";

    li.appendChild(label);
    li.appendChild(del);
    el.habitList.appendChild(li);
  });
}

function render() {
  renderStats();
  renderList();
}

async function persist(nextHabits, nextCheckins) {
  const current = await appStore.getState();
  const base = current && typeof current === "object" ? current : {};
  const next = Object.assign({}, base);
  next[HABITS_KEY] = nextHabits;
  next[CHECKINS_KEY] = nextCheckins;
  await appStore.setState(next);
}

async function addHabit(name) {
  const trimmed = name.trim();
  if (!trimmed) {
    setMessage("请输入习惯名称。", "error");
    el.nameInput.focus();
    return;
  }
  const duplicate = habits.some(function (h) {
    return h.name.trim() === trimmed;
  });
  if (duplicate) {
    setMessage("已存在同名习惯，请换一个名称。", "error");
    el.nameInput.focus();
    return;
  }

  const habit = normalizeHabit({ id: makeId(), name: trimmed, createdAt: new Date().toISOString() });
  const nextHabits = habits.concat([habit]);

  try {
    await persist(nextHabits, checkins);
  } catch (err) {
    setMessage("保存失败，请重试。习惯未添加。", "error");
    return;
  }

  habits.push(habit);
  el.nameInput.value = "";
  setMessage("已添加习惯：" + habit.name, "ok");
  render();
  el.nameInput.focus();
}

async function toggleHabit(habitId, done) {
  const day = todayKey();
  const dayMap = checkins[day] && typeof checkins[day] === "object" ? Object.assign({}, checkins[day]) : {};
  if (done) {
    dayMap[habitId] = true;
  } else {
    delete dayMap[habitId];
  }
  const nextCheckins = Object.assign({}, checkins);
  if (Object.keys(dayMap).length > 0) {
    nextCheckins[day] = dayMap;
  } else {
    delete nextCheckins[day];
  }

  try {
    await persist(habits, nextCheckins);
  } catch (err) {
    setMessage("保存失败，打卡状态未更新。", "error");
    render();
    return;
  }

  checkins[day] = dayMap;
  if (Object.keys(dayMap).length === 0) delete checkins[day];
  setMessage("", "");
  render();
}

let pendingDeleteId = null;

function openDeleteDialog(habit) {
  pendingDeleteId = habit.id;
  el.dialogText.textContent = "确定要删除习惯「" + habit.name + "」吗？该习惯的打卡记录也会一并移除，此操作不可撤销。";
  el.dialogBackdrop.hidden = false;
  el.dialogConfirm.focus();
}

function closeDeleteDialog() {
  pendingDeleteId = null;
  el.dialogBackdrop.hidden = true;
}

async function confirmDelete() {
  const id = pendingDeleteId;
  if (!id) {
    closeDeleteDialog();
    return;
  }
  const target = habits.find(function (h) { return h.id === id; });
  if (!target) {
    closeDeleteDialog();
    return;
  }

  const nextHabits = habits.filter(function (h) { return h.id !== id; });
  const nextCheckins = {};
  Object.keys(checkins).forEach(function (day) {
    const dayMap = checkins[day];
    if (!dayMap || typeof dayMap !== "object") return;
    const copy = Object.assign({}, dayMap);
    delete copy[id];
    if (Object.keys(copy).length > 0) nextCheckins[day] = copy;
  });

  try {
    await persist(nextHabits, nextCheckins);
  } catch (err) {
    closeDeleteDialog();
    setMessage("删除失败，请重试。习惯仍保留。", "error");
    return;
  }

  const idx = habits.findIndex(function (h) { return h.id === id; });
  if (idx >= 0) habits.splice(idx, 1);
  Object.keys(checkins).forEach(function (day) { delete checkins[day]; });
  Object.keys(nextCheckins).forEach(function (day) { checkins[day] = nextCheckins[day]; });

  closeDeleteDialog();
  setMessage("已删除习惯：" + target.name, "ok");
  render();
}

async function init() {
  el.todayLabel.textContent = todayText();

  el.addForm.addEventListener("submit", function (event) {
    event.preventDefault();
    addHabit(el.nameInput.value).catch(function () {
      setMessage("保存失败，请重试。", "error");
    });
  });

  el.habitList.addEventListener("change", function (event) {
    const target = event.target;
    if (!target || target.dataset.role !== "toggle") return;
    const item = target.closest(".habit-item");
    if (!item) return;
    toggleHabit(item.dataset.habitId, target.checked).catch(function () {
      setMessage("保存失败，打卡状态未更新。", "error");
      render();
    });
  });

  el.habitList.addEventListener("click", function (event) {
    const target = event.target;
    if (!target || target.dataset.role !== "delete") return;
    const item = target.closest(".habit-item");
    if (!item) return;
    const habit = habits.find(function (h) { return h.id === item.dataset.habitId; });
    if (habit) openDeleteDialog(habit);
  });

  el.dialogCancel.addEventListener("click", function () {
    closeDeleteDialog();
  });

  el.dialogConfirm.addEventListener("click", function () {
    confirmDelete().catch(function () {
      closeDeleteDialog();
      setMessage("删除失败，请重试。", "error");
    });
  });

  el.dialogBackdrop.addEventListener("click", function (event) {
    if (event.target === el.dialogBackdrop) closeDeleteDialog();
  });

  document.addEventListener("keydown", function (event) {
    if (event.key === "Escape" && !el.dialogBackdrop.hidden) closeDeleteDialog();
  });

  if (!existingHabits) {
    try {
      await persist(habits, checkins);
    } catch (err) {
      setMessage("初始化数据保存失败，新增内容可能无法保留。", "error");
    }
  }

  render();
}

await init();

