:root {
  --bg: #0f1b2a;
  --bg-soft: #16263a;
  --surface: #1c2f47;
  --surface-2: #223a56;
  --border: #2f4a6b;
  --text: #eaf2fb;
  --text-dim: #9fb4cc;
  --accent: #35d0a5;
  --accent-strong: #22b98f;
  --accent-soft: rgba(53, 208, 165, 0.16);
  --danger: #ff6b6b;
  --danger-soft: rgba(255, 107, 107, 0.14);
  --shadow: 0 18px 40px rgba(3, 10, 20, 0.45);
  --radius: 16px;
}

#app {
  min-height: 100vh;
  background: radial-gradient(1200px 600px at 15% -10%, #1d3a56 0%, transparent 60%),
    radial-gradient(900px 500px at 100% 0%, #1a4a45 0%, transparent 55%),
    var(--bg);
  color: var(--text);
  font-family: "PingFang SC", "Hiragino Sans GB", "Microsoft YaHei", system-ui, -apple-system, "Segoe UI", sans-serif;
  font-size: 16px;
  line-height: 1.55;
  -webkit-font-smoothing: antialiased;
}

#app *,
#app *::before,
#app *::after {
  box-sizing: border-box;
}

.app-shell {
  min-height: 100vh;
  width: 100%;
  max-width: 760px;
  margin: 0 auto;
  padding: 32px 20px 64px;
  display: flex;
  flex-direction: column;
  gap: 22px;
}

.app-header {
  display: flex;
  flex-direction: column;
  gap: 16px;
}

.header-top {
  display: flex;
  flex-wrap: wrap;
  align-items: baseline;
  justify-content: space-between;
  gap: 8px;
}

.app-title {
  margin: 0;
  font-size: 28px;
  font-weight: 700;
  letter-spacing: 0.02em;
  color: var(--text);
}

.app-date {
  margin: 0;
  font-size: 14px;
  color: var(--text-dim);
}

.stat-card {
  background: linear-gradient(160deg, var(--surface-2), var(--surface));
  border: 1px solid var(--border);
  border-radius: var(--radius);
  padding: 20px 22px;
  box-shadow: var(--shadow);
}

.stat-main {
  display: flex;
  align-items: baseline;
  gap: 8px;
  color: var(--text);
}

.stat-number {
  font-size: 44px;
  font-weight: 700;
  line-height: 1;
  color: var(--accent);
}

.stat-divider {
  font-size: 24px;
  color: var(--text-dim);
}

.stat-total {
  font-size: 24px;
  font-weight: 600;
  color: var(--text-dim);
}

.stat-caption {
  margin: 6px 0 14px;
  font-size: 14px;
  color: var(--text-dim);
}

.progress-track {
  height: 8px;
  width: 100%;
  border-radius: 999px;
  background: rgba(255, 255, 255, 0.08);
  overflow: hidden;
}

.progress-fill {
  height: 100%;
  width: 0%;
  border-radius: 999px;
  background: linear-gradient(90deg, var(--accent-strong), var(--accent));
  transition: width 0.28s ease;
}

.app-main {
  display: flex;
  flex-direction: column;
  gap: 22px;
}

.panel {
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  padding: 20px 22px;
  box-shadow: var(--shadow);
}

.panel-title {
  margin: 0 0 14px;
  font-size: 17px;
  font-weight: 600;
  color: var(--text);
}

.add-form {
  display: flex;
  flex-wrap: wrap;
  align-items: flex-end;
  gap: 12px;
}

.field {
  flex: 1 1 220px;
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.field-label {
  font-size: 13px;
  color: var(--text-dim);
}

.field-input {
  width: 100%;
  padding: 11px 13px;
  font-size: 15px;
  font-family: inherit;
  color: var(--text);
  background: var(--bg-soft);
  border: 1px solid var(--border);
  border-radius: 10px;
  outline: none;
  transition: border-color 0.18s ease, box-shadow 0.18s ease;
}

.field-input::placeholder {
  color: #6f88a3;
}

.field-input:focus {
  border-color: var(--accent);
  box-shadow: 0 0 0 3px var(--accent-soft);
}

.btn {
  font-family: inherit;
  font-size: 15px;
  font-weight: 600;
  padding: 11px 18px;
  border-radius: 10px;
  border: 1px solid transparent;
  cursor: pointer;
  transition: transform 0.12s ease, background 0.18s ease, border-color 0.18s ease, color 0.18s ease;
}

.btn:active {
  transform: translateY(1px);
}

.btn:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: 2px;
}

.btn-primary {
  background: var(--accent);
  color: #06231b;
}

.btn-primary:hover {
  background: var(--accent-strong);
}

.btn-ghost {
  background: transparent;
  color: var(--text-dim);
  border-color: var(--border);
}

.btn-ghost:hover {
  color: var(--text);
  border-color: var(--text-dim);
}

.btn-danger {
  background: var(--danger);
  color: #2b0707;
}

.btn-danger:hover {
  background: #ff5252;
}

.form-message {
  margin: 10px 0 0;
  min-height: 20px;
  font-size: 13px;
  color: var(--text-dim);
}

.form-message.is-error {
  color: var(--danger);
}

.form-message.is-ok {
  color: var(--accent);
}

.list-head {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 10px;
}

.list-head .panel-title {
  margin-bottom: 14px;
}

.list-count {
  font-size: 13px;
  color: var(--text-dim);
}

.habit-list {
  list-style: none;
  margin: 0;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.habit-item {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 12px 14px;
  background: var(--bg-soft);
  border: 1px solid var(--border);
  border-radius: 12px;
  transition: border-color 0.18s ease, background 0.18s ease;
}

.habit-item.is-done {
  border-color: var(--accent);
  background: var(--accent-soft);
}

.habit-check {
  flex: 0 0 auto;
  width: 22px;
  height: 22px;
  accent-color: var(--accent);
  cursor: pointer;
}

.habit-label {
  flex: 1 1 auto;
  display: flex;
  align-items: center;
  gap: 10px;
  cursor: pointer;
  min-width: 0;
}

.habit-name {
  font-size: 16px;
  color: var(--text);
  word-break: break-word;
}

.habit-item.is-done .habit-name {
  color: var(--accent);
}

.habit-meta {
  font-size: 12px;
  color: var(--text-dim);
  white-space: nowrap;
}

.habit-delete {
  flex: 0 0 auto;
  font-family: inherit;
  font-size: 13px;
  padding: 7px 12px;
  border-radius: 9px;
  border: 1px solid var(--border);
  background: transparent;
  color: var(--text-dim);
  cursor: pointer;
  transition: color 0.18s ease, border-color 0.18s ease, background 0.18s ease;
}

.habit-delete:hover {
  color: var(--danger);
  border-color: var(--danger);
  background: var(--danger-soft);
}

.empty-state {
  margin: 4px 0 0;
  padding: 22px 16px;
  text-align: center;
  font-size: 14px;
  color: var(--text-dim);
  border: 1px dashed var(--border);
  border-radius: 12px;
}

.dialog-backdrop {
  position: fixed;
  inset: 0;
  background: rgba(5, 12, 22, 0.68);
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 20px;
  z-index: 50;
}

.dialog-backdrop[hidden] {
  display: none;
}

.dialog {
  width: 100%;
  max-width: 380px;
  background: var(--surface-2);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  padding: 22px;
  box-shadow: var(--shadow);
}

.dialog-title {
  margin: 0 0 10px;
  font-size: 17px;
  color: var(--text);
}

.dialog-text {
  margin: 0 0 18px;
  font-size: 14px;
  color: var(--text-dim);
  word-break: break-word;
}

.dialog-actions {
  display: flex;
  justify-content: flex-end;
  gap: 10px;
}

@media (max-width: 480px) {
  .app-shell {
    padding: 22px 14px 48px;
  }

  .stat-number {
    font-size: 36px;
  }

  .add-form {
    flex-direction: column;
    align-items: stretch;
  }

  .btn-primary {
    width: 100%;
  }
}
